# Generates MiscClasses.h/.cpp + targets_misc.txt for the plain Function subclasses whose small slots follow a known shape.
use strict; use Digest::MD5 qw(md5_hex);
chdir "../../.." or die;
my $exe = do { local $/; open my $f, "<:raw", "Exported/SQZ.EXE" or die; <$f> };
sub rva2off { my ($va) = @_; my $pe = unpack('V', substr($exe,0x3c,4)); my ($nsec,$opt) = unpack('x6 v x12 v', substr($exe,$pe,24)); my $base = unpack('V', substr($exe,$pe+24+28,4));
  for my $i (0..$nsec-1) { my ($vs,$va0,$rs,$rp) = unpack('x8 V V V V', substr($exe,$pe+24+$opt+$i*40,40)); my $r = $va-$base; return $rp+$r-$va0 if $r >= $va0 && $r < $va0+$vs; } die }
sub cstr { my ($va) = @_; return unpack('Z*', substr($exe, rva2off($va), 64)); }
sub bytes { my ($va,$n) = @_; return substr($exe, rva2off($va), $n); }
my %fsz; { open my $ff, "<nm/fns_all.txt" or die; while (<$ff>) { $fsz{hex($1)} = $2 if /^([0-9a-f]+) size=(\d+)/ } }
sub sizearg { my ($a) = @_; return "" if exists $fsz{$a}; for my $s (keys %fsz) { return " " . ($s + $fsz{$s} - $a) if $s < $a && $a < $s + $fsz{$s} } return "" }
sub sddsize { my ($a) = @_; my $best = 0; my $n = $fsz{$a} // 128; my $b = bytes($a, $n + 64);
  for my $i (0..$n-5) { next unless substr($b,$i,1) eq "\xe8"; my $t = $a + $i + 5 + unpack('l', substr($b,$i+1,4)); $best = $t + 8 - $a if $t > $a + $n - 8 && $t < $a + $n + 40 && $t + 8 - $a > $best; }
  return $best || $n; }
sub ccsize { my ($a) = @_; my $b = bytes($a, 700); my $i = 4; $i++ while $i < 698 && substr($b,$i,2) ne "лл"; return $i }
sub norm { my ($a) = @_; my $n = $fsz{$a} || ccsize($a); my $e = sprintf("0x%x", $a + $n);
  my @l = `objdump -d -M intel --start-address=$a --stop-address=$e Exported/SQZ.EXE`; my @o;
  for (@l) { s/\r//; next unless /^\s*[0-9a-f]+:\t[0-9a-f ]+\t(.+?)\s*$/; my $t = $1; $t =~ s/\s+/ /g; $t =~ s/0x[0-9a-f]{5,}/X/g; push @o, $t }
  return substr(md5_hex(join("|", @o)), 0, 6); }
sub calls { my ($a) = @_; my $n = $fsz{$a} // 0; my $b = bytes($a, $n); my @t; for my $i (0..$n-5) { push @t, $a + $i + 5 + unpack('l', substr($b,$i+1,4)) if substr($b,$i,1) eq "\xe8" } return @t }
my %done = map { $_ => 1 } qw(KillSqueezil GoToRegion);
open R, "<tools/rtti.tsv"; my @cls;
while (<R>) { chomp; my @f = split /\t/; next unless $f[0] =~ /^\.\?AV(\w+Function)\@\@$/; my $cn = $1; next if $cn =~ /Argument|^If|^TweakFloat/ || ($f[3] // '') =~ /Tweak|AVIf/; next if $done{(my $s = $cn) =~ s/Function$//r}; next unless ($f[3] // '') =~ /^\.\?AVFunction\@\@$/; next unless $f[4] =~ /;/; my @s = map { hex } split /;/, $f[4]; push @cls, [$cn, hex($f[1]), @s]; }
my $q = '^' . chr(92) . '?'; my $bs = chr(92);
my (@h, @c, @t); my %stat;
for my $c (@cls) {
  my ($n, $vt, $sdd, $exec, $create, $print, $name) = @$c; (my $short = $n) =~ s/Function$//;
  my ($hs, $hc, $hp) = (norm($sdd), norm($create), norm($print));
  my $kind;
  if ($hc eq '64c4a4' && $hp eq '604774') { $kind = 'noarg' }
  elsif ($hc eq '2fe4ad' && $hp eq 'd7ce06') { $kind = 'float' }
  else { $stat{skipped}++; next }
  my $nb = bytes($name, 6); my $str = (unpack('C', $nb) == 0xb8) ? cstr(unpack('V', substr($nb,1,4))) : next;
  my $dtorExt = ($hs eq 'f96d83') ? ((calls($sdd))[0]) : undef;
  my $declDtor = ($hs eq '53d7bf') ? "    ~$n() {}
" : ($hs eq 'c566a0') ? "    ~$n() { delete arg; }
" : ($dtorExt ? "    ~$n();
" : '');
  my $member = $kind eq 'float' ? "    FloatFunctionArgument *arg;                          // 0x04\n" : '';
  push @h, "class $n : public Function {\npublic:\n" . ($kind eq 'float' ? "    $n() { arg = 0; }\n" : '') . $declDtor . "    virtual int Execute(ScriptCall *args, int extra);\n    virtual Function *Create(ArgList *list);\n    virtual void Print();\n    virtual const char *Name();\n$member};\n";
  my $b = '';
  $b .= "const char *$n\::Name() { return \"$str\"; }\n";
  if ($kind eq 'noarg') { $b .= "Function *$n\::Create(ArgList *list) { return new $n; }\nvoid $n\::Print() { DebugLogAll(\"%s\", Name()); }\n"; }
  else { $b .= "Function *$n\::Create(ArgList *list)\n{\n    $n *f = new $n;\n    f->arg = ParseFloatArgument(list);\n    return f;\n}\nvoid $n\::Print()\n{\n    DebugLogAll(\"%s\", Name());\n    arg->Print();\n    DebugLogAll(\"" . chr(92) . "n\");\n}\n"; }
  if ($dtorExt) { $b .= "$n\::~$n()\n{\n    if (arg)\n        delete arg;\n}\n"; push @t, $q . $bs . "?1$n" . "  " . sprintf("%x", $dtorExt) . " ${short}_dtor " . sddsize($dtorExt - 0) . "\n"; }
  push @c, $b;
  push @t, $q . "Name\@$n  " . sprintf("%x", $name) . " ${short}_name\n" . $q . "Create\@$n  " . sprintf("%x", $create) . " ${short}_create" . '' . "\n" . $q . "Print\@$n  " . sprintf("%x", $print) . " ${short}_print\n" . $q . $bs . "?_G$n  " . sprintf("%x", $sdd) . " ${short}_sdd " . sddsize($sdd) . "\n";
  $stat{$kind}++;
}
open H, ">Repo/src/FunctionMisc/MiscClasses.h"; print H "// Plain Function subclasses (generated by gen.pl).\n#pragma once\n#include \"FunctionArgs/FunctionArgs.h\"\n\nclass FloatFunctionArgument : public FunctionArgument {   // vtable 0x49da84\npublic:\n    FloatFunctionArgument();\n    virtual void Print();                               // 0x421410\n    float value;                                        // 0x0c\n    float Get(int context);                             // 0x421440\n};\nFloatFunctionArgument *ParseFloatArgument(ArgList *list);   // 0x421250 (cdecl)\n\n", join("\n", @h); close H;
open C, ">Repo/src/FunctionMisc/MiscClasses.cpp"; print C "// Small slots of the plain Function subclasses (generated by gen.pl).\n#include \"FunctionMisc/MiscClasses.h\"\n\n", join("\n", @c); close C;
open T, ">Repo/src/FunctionMisc/targets_misc.txt"; print T @t; close T;
print join(" ", map { "$_=$stat{$_}" } sort keys %stat), "\n";
